def migrate_simulated_payments_to_cod(apps, schema_editor):
    Order = apps.get_model("orders", "Order")
    Payment = apps.get_model("orders", "Payment")

    Order.objects.filter(status="AWAITING_PAYMENT").update(status="AWAITING_CONFIRMATION")
    Order.objects.filter(status="PAID").update(status="CONFIRMED")

    # The old implementation allowed repeated simulated card attempts. COD has
    # exactly one collection record per order, so retain the newest record and
    # discard obsolete simulation attempts before adding the one-to-one key.
    for order_id in Payment.objects.values_list("order_id", flat=True).distinct():
        records = Payment.objects.filter(order_id=order_id).order_by("-created_at", "-pk")
        keeper = records.first()
        records.exclude(pk=keeper.pk).delete()
        keeper.status = "PENDING"
        keeper.method = "CASH_ON_DELIVERY"
        keeper.collection_note = "Migrated from the retired simulated-card workflow."
        keeper.collected_at = None
        keeper.save(update_fields=["status", "method", "collection_note", "collected_at"])


def reverse_cod_statuses(apps, schema_editor):
    Order = apps.get_model("orders", "Order")
    Payment = apps.get_model("orders", "Payment")
    Order.objects.filter(status="AWAITING_CONFIRMATION").update(status="AWAITING_PAYMENT")
    Order.objects.filter(status="CONFIRMED").update(status="PAID")
    Payment.objects.filter(status="COLLECTED").update(status="SUCCESSFUL")
    Payment.objects.filter(status="NOT_COLLECTED").update(status="FAILED")
    Payment.objects.all().update(method="CARD")


